package cn.vie.vibe.gallery.infrastructure;
import cn.vie.vibe.gallery.application.*; import io.minio.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.Profile; import org.springframework.stereotype.Component; import java.io.*; import java.net.URI;
@Component @Profile("!dev-memory") public class MinioObjectStorage implements ObjectStoragePort { private final MinioClient client; private final String endpoint; private final String publicEndpoint; private final String bucket; public MinioObjectStorage(@Value("${gallery.storage.endpoint:http://localhost:9000}")String e,@Value("${gallery.storage.public-endpoint:}")String pub,@Value("${gallery.storage.access-key:vie_local}")String a,@Value("${gallery.storage.secret-key:vie_local_secret}")String s,@Value("${gallery.storage.bucket:vie-gallery}")String b){endpoint=e;publicEndpoint=pub;client=MinioClient.builder().endpoint(e).credentials(a,s).build();bucket=b; ensureBucket();} private void ensureBucket(){try{if(!client.bucketExists(BucketExistsArgs.builder().bucket(bucket).build())) client.makeBucket(MakeBucketArgs.builder().bucket(bucket).build());}catch(Exception ex){throw new IllegalStateException("Object storage unavailable",ex);}} public StoredObject put(String key,InputStream in,String type,long size){try{client.putObject(PutObjectArgs.builder().bucket(bucket).object(key).stream(in,size,-1).contentType(type).build());return new StoredObject(bucket,key,null,size,null,null,"");}catch(Exception e){throw new IllegalStateException(e);}} public InputStream get(String key){try{return client.getObject(GetObjectArgs.builder().bucket(bucket).object(key).build());}catch(Exception e){throw new IllegalStateException(e);}} public void delete(String key){try{client.removeObject(RemoveObjectArgs.builder().bucket(bucket).object(key).build());}catch(Exception e){throw new IllegalStateException(e);}} public URI createReadUrl(String key){String base=(publicEndpoint!=null&&!publicEndpoint.isBlank())?publicEndpoint:endpoint;if(!base.endsWith("/")) base+="/";return URI.create(base+bucket+"/"+key);} }
